export const session_messageSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"AgentUsage":{"description":"Token usage reported by the provider for one agent turn.\n\nThe counters are required (a `usage` object is only present when the provider reported usage; unreported counters are normalized to `0` by the runtime), matching `specs/changes/2026-10-31-config-and-media/spec.md`. `cost_micros` stays optional because most providers do not report cost.","properties":{"cached_tokens":{"description":"The part of `input_tokens` read from a provider-managed cache.","format":"uint64","minimum":0.0,"type":"integer"},"cost_micros":{"description":"Provider-reported cost in micro-USD (1e-6 USD), when known.","format":"uint64","minimum":0.0,"type":["integer","null"]},"input_tokens":{"description":"Every input token (cached + uncached).","format":"uint64","minimum":0.0,"type":"integer"},"output_tokens":{"description":"Every output token, reasoning included.","format":"uint64","minimum":0.0,"type":"integer"},"reasoning_tokens":{"description":"The part of `output_tokens` spent on internal reasoning.","format":"uint64","minimum":0.0,"type":"integer"},"total_tokens":{"description":"`input_tokens + output_tokens`.","format":"uint64","minimum":0.0,"type":"integer"}},"required":["cached_tokens","input_tokens","output_tokens","reasoning_tokens","total_tokens"],"type":"object"}},"description":"One message inside a conversation.","properties":{"content":{"description":"Text content (tool records are JSON strings in M1).","type":"string"},"conversation_id":{"description":"Parent conversation id.","type":"string"},"created_at_ms":{"description":"Creation time (ms since epoch).","format":"uint64","minimum":0.0,"type":"integer"},"id":{"description":"Stable id.","type":"string"},"role":{"description":"Role: `user` | `assistant` | `tool` | `system`.","type":"string"},"status":{"default":"done","description":"Turn status: `done` | `cancelled` | `error` (M1 persistence for cancel markers).","type":"string"},"usage":{"anyOf":[{"$ref":"#/definitions/AgentUsage"},{"type":"null"}],"default":null,"description":"Provider token usage for an assistant turn, when reported.\n\nPersisted so usage survives restarts (round-4); legacy rows parse as `None`."}},"required":["content","conversation_id","created_at_ms","id","role"],"title":"Message","type":"object"} as const;

export const skill_catalogSchema = {"$schema":"http://json-schema.org/draft-07/schema#","description":"Catalog entry returned by `GET /api/client/v1/skills`.","properties":{"can_install":{"type":"boolean"},"category":{"type":"string"},"enforced":{"type":"boolean"},"min_client_version":{"type":"string"},"name":{"type":"string"},"sha256":{"type":"string"},"title":{"type":"string"},"version":{"type":"string"}},"required":["can_install","category","enforced","min_client_version","name","sha256","title","version"],"title":"SkillCatalogEntry","type":"object"} as const;

